def _cleanup_container(self, cinfo):
        """
        Remove a container and clean up its image if necessary.
        """
        if not cinfo:
            return

        if cinfo.get('container'):
            self.docker_client.remove_container(cinfo['container'])
        if cinfo.get('image'):
            self.docker_client.remove_image(cinfo['image'])

